mapper.sql:
(SELECT idt.purchase_arrival_detail_id AS purchase_arrival_detail_id, sum(idt.pass_qty) AS pass_qty, sum(idt.fail_qty) AS fail_qty FROM tb_quality_inspection_dt idt JOIN tb_quality_inspection_hd ih ON ih.quality_inspection_id = idt.quality_inspection_id AND ih.tenant_id = idt.tenant_id WHERE ih.tenant_id = #{tenantId, jdbcType=BIGINT} AND ih.use_at = 'Y' AND idt.purchase_arrival_detail_id IS NOT NULL
AND ih.quality_inspection_id <> #{excludeInspectionId, jdbcType=BIGINT}
GROUP BY idt.purchase_arrival_detail_id)

mapper.select:
SELECT u.user_id AS userId,
       u.department_id AS departmentId
FROM tb_user u
WHERE u.user_id = #{userId, jdbcType=BIGINT}
  AND u.tenant_id = #{tenantId, jdbcType=BIGINT}
  AND u.use_at = 'Y'

INSERT INTO tb_quality_inspection_hd (
    tenant_id, inspection_no, inspection_dt, inspector_id, inspector_dept_id, remark, created_by
)
SELECT t.tenant_id, #{inspectionNo}, CAST(#{inspectionDt} AS date), #{inspectorId, jdbcType=BIGINT},
       #{inspectorDeptId, jdbcType=BIGINT}, #{remark}, #{createdBy}
FROM tb_tenant t
WHERE t.tenant_id = #{tenantId, jdbcType=BIGINT}
RETURNING quality_inspection_id

INSERT INTO tb_quality_inspection_dt (
    quality_inspection_id, tenant_id, line_no, purchase_arrival_detail_id, arrival_no,
    purchase_order_detail_id, material_id, pass_qty, fail_qty, remark, created_by
) VALUES (
    #{qualityInspectionId, jdbcType=BIGINT}, #{tenantId, jdbcType=BIGINT}, #{lineNo},
    #{purchaseArrivalDetailId, jdbcType=BIGINT}, #{arrivalNo},
    #{purchaseOrderDetailId, jdbcType=BIGINT}, #{materialId, jdbcType=BIGINT},
    #{passQty, jdbcType=NUMERIC}, #{failQty, jdbcType=NUMERIC}, #{remark}, #{createdBy}
)
RETURNING quality_inspection_detail_id

mapper.update:
UPDATE tb_quality_inspection_dt
SET line_no = #{lineNo},
    pass_qty = #{passQty, jdbcType=NUMERIC},
    fail_qty = #{failQty, jdbcType=NUMERIC},
    remark = #{remark},
    updated_by = #{updatedBy},
    updated_at = now()
WHERE quality_inspection_detail_id = #{qualityInspectionDetailId, jdbcType=BIGINT}
  AND quality_inspection_id = #{qualityInspectionId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}

mapper.delete:
DELETE FROM tb_quality_inspection_dt
WHERE quality_inspection_detail_id = #{qualityInspectionDetailId, jdbcType=BIGINT}
  AND quality_inspection_id = #{qualityInspectionId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
